basic.source:
plan basic {
  source lib : smiles at "compounds.smi"
  let raw := read lib
  let mols := translate raw require element, connectivity else report
  emit mols with provenance
}

refused.source:
plan needs_geometry {
  source lib : smiles at "compounds.smi"
  let raw := read lib
  let mols := translate raw require element, connectivity, coords3d else refuse
  emit mols
}

threshold.source:
plan low {
  source lib : smiles at "compounds.smi"
  let raw := read lib
  let mols := translate raw require element, connectivity expect supplied < 0.25 else report
  emit mols with provenance
}

parse-error.source:
plan bad {
  source lib : smiles at "x.smi"
  let raw := read lib
  let mols := translate raw require element bogus
}
